# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM ESTETİĞİNİN VE SANAT ANLAYIŞININ TEMEL İLKELERİ</text>\n  <rect x="20" y="48" width="210" height="182" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">1. Cemâl ve İhsan Bilinci</text>\n  <text x="32" y="98" font-size="10.5" fill="#334155">• \'Allah güzeldir, güzelliği sever\'</text>\n  <text x="40" y="113" font-size="10" fill="#475569">hadisi estetik rehberdir.</text>\n  <text x="32" y="138" font-size="10.5" fill="#334155">• el-Cemîl, el-Bedî\' ve el-Musavvir</text>\n  <text x="40" y="153" font-size="10" fill="#475569">isimlerinin tecellisi aranır.</text>\n  <text x="32" y="178" font-size="10.5" fill="#334155">• Her eser \'ihsan\' (en güzel ve</text>\n  <text x="40" y="193" font-size="10" fill="#475569">kusursuz yapma) ahlakıyla üretilir.</text>\n\n  <rect x="245" y="48" width="210" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. Tevhid ve Tenzih İlkesi</text>\n  <text x="257" y="98" font-size="10.5" fill="#334155">• Putperestlik çağrışımlarından</text>\n  <text x="265" y="113" font-size="10" fill="#475569">titizlikle kaçınılmıştır.</text>\n  <text x="257" y="138" font-size="10.5" fill="#334155">• Doğrudan taklit yerine soyutlama</text>\n  <text x="265" y="153" font-size="10" fill="#475569">ve üsluplaştırma (stilizasyon) vardır.</text>\n  <text x="257" y="178" font-size="10.5" fill="#334155">• Geometrik yıldız ve geçmelerle</text>\n  <text x="265" y="193" font-size="10" fill="#475569">ilahi birlik ve sonsuzluk anlatılır.</text>\n\n  <rect x="470" y="48" width="210" height="182" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. Tenasüp ve Tevazü</text>\n  <text x="482" y="98" font-size="10.5" fill="#334155">• Eserlerde ölçü, simetri ve</text>\n  <text x="490" y="113" font-size="10" fill="#475569">uyum (tenasüp) esastır.</text>\n  <text x="482" y="138" font-size="10.5" fill="#334155">• Sanatçı kibre kapılmaz; imzasını</text>\n  <text x="490" y="153" font-size="10" fill="#475569">\'ketebe el-fakîr\' diye tevazuyla atar.</text>\n  <text x="482" y="178" font-size="10.5" fill="#334155">• Sanat insanı maddeye değil,</text>\n  <text x="490" y="193" font-size="10" fill="#475569">hakikate ve huzura yöneltir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE GELENEKSEL SANATLAR VE USTALARI</text>\n  <rect x="20" y="45" width="320" height="92" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">1. Hüsnühat (Sanatçı: Hattat)</text>\n  <text x="32" y="86" font-size="10.5" fill="#334155">• Kamış kalem ve is mürekkebiyle estetik yazı sanatıdır.</text>\n  <text x="32" y="104" font-size="10.5" fill="#334155">• Türler: Kûfî, Sülüs, Nesih, Ta\'lîk, Rik\'a, Divânî.</text>\n  <text x="32" y="122" font-size="10" font-weight="bold" fill="#6d28d9">Ustalar: Şeyh Hamdullah, Karahisârî, Hâfız Osman</text>\n\n  <rect x="360" y="45" width="320" height="92" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Tezhip (Sanatçı: Müzehhip)</text>\n  <text x="372" y="86" font-size="10.5" fill="#334155">• Altın tozu ve boyayla mushaf ve levha süsleme sanatıdır.</text>\n  <text x="372" y="104" font-size="10.5" fill="#334155">• Hataî, rumî, penç ve bulut motifleri kullanılır.</text>\n  <text x="372" y="122" font-size="10" font-weight="bold" fill="#b45309">Ustalar: Şahkulu (Saz üslubu), Kara Memi</text>\n\n  <rect x="20" y="150" width="320" height="92" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="180" y="171" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0369a1">3. Ebru (Sanatçı: Ebruzen)</text>\n  <text x="32" y="191" font-size="10.5" fill="#334155">• Kitreli su üzerine serpilen boyaların kâğıda aktarımıdır.</text>\n  <text x="32" y="209" font-size="10.5" fill="#334155">• Battal, gelgit, şal, bülbülyuvası ve çiçekli ebru türleri.</text>\n  <text x="32" y="227" font-size="10" font-weight="bold" fill="#0284c7">Ustalar: Hatip Mehmed Efendi, Mustafa Düzgünman</text>\n\n  <rect x="360" y="150" width="320" height="92" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="520" y="171" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">4. Minyatür / Nakış (Sanatçı: Nakkaş)</text>\n  <text x="372" y="191" font-size="10.5" fill="#334155">• Işık-gölge ve perspektif içermeyen iki boyutlu tasvirdir.</text>\n  <text x="372" y="209" font-size="10.5" fill="#334155">• Boyutlar perspektife göre değil, kişinin önemine göredir.</text>\n  <text x="372" y="227" font-size="10" font-weight="bold" fill="#166534">Ustalar: Matrakçı Nasuh, Nakkaş Osman, Levnî</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE MİMARİ VE DİNÎ MUSİKİ</text>\n  <rect x="25" y="48" width="310" height="182" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. İslam Mimarisi ve Külliye</text>\n  <text x="40" y="98" font-size="10.5" fill="#334155">• Merkezde cami; çevresinde medrese, şifahane,</text>\n  <text x="48" y="113" font-size="10" fill="#475569">imaret, kütüphane ve sebilden oluşan \'Külliye\'.</text>\n  <text x="40" y="136" font-size="10.5" fill="#334155">• Çini, kalemişi, kündekârî (ahşap) ve hüsnühat</text>\n  <text x="48" y="151" font-size="10" fill="#475569">mimari yapı içinde bütünleşir.</text>\n  <rect x="42" y="166" width="276" height="50" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.2"/>\n  <text x="180" y="185" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Mimar Sinan\'ın Üç Büyük Eseri:</text>\n  <text x="180" y="202" text-anchor="middle" font-size="10" fill="#334155">Şehzade (Çıraklık) · Süleymaniye · Selimiye (Ustalık)</text>\n\n  <rect x="365" y="48" width="310" height="182" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Cami ve Tasavvuf Musikisi</text>\n  <text x="380" y="98" font-size="10.5" fill="#334155">• Cami Musikisi: Ezan, Kamet, Salâ, Mevlit,</text>\n  <text x="388" y="113" font-size="10" fill="#475569">Tekbir, Telbiye, Cumhur Müezzinliği.</text>\n  <text x="380" y="136" font-size="10.5" fill="#334155">• Tasavvuf Musikisi: İlahi, Naat, Kaside, Âyin.</text>\n  <rect x="382" y="166" width="276" height="50" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="520" y="185" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Öncü Âlim ve Bestekârlar:</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10" fill="#334155">Fârâbî · Buhûrîzâde Itrî (Segâh Tekbir) · Dede Efendi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
